import{_ as n,l as i,o as e,c as s,v as t,p as l,x as r,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"影子银行挤兑","description":"","frontmatter":{"title":"影子银行挤兑","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/shadow-run.md","filePath":"econ/shadow-run.md","lastUpdated":1789023840000}'),p={name:"econ/shadow-run.md"};function u(E,a,_,m,A,B){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="影子银行挤兑" tabindex="-1">影子银行挤兑 <a class="header-anchor" href="#影子银行挤兑" aria-label="Permalink to &quot;影子银行挤兑&quot;">​</a></h1><div class="epigraph"><p>不受存款保险覆盖的短债，一样可以挤兑。2008 年停的是 ABCP、回购和货币市场基金份额，不只是柜面排队。</p><footer>—— Gorton and Metrick, Securitized Banking and the Run on Repo, JFE 2012；Covitz, Liang and Suarez 的 ABCP 挤兑</footer></div><p><a href="/econ/banking-crises-history">上一课</a>把模式钉在信贷与短债上。缺口是：许多短债不在银行牌照里。本课钉影子挤兑；央行表下一课才讲谁来买这些资产。不重写 DD 的存款合约。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>影子银行用证券化、回购、ABCP 把长期资产做成「信息不敏感」的短债（Gorton）。haircut 或展期一旦跳升，等同挤兑：不是取现金，是不再续作。2007–08 的 ABCP 与回购是这一机制的现场。若模型里只有受保存款，会把危机写成「监管没覆盖的边角」，而不是核心滚动市场。</p><p><span class="marginnote">Pozsar 等人的影子银行地图。Krishnamurthy, Nagel and Orlov 的回购。Run on repo 的定量大小有争论，机制仍是 haircut 与停滚。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把影子负债当成与存款同类的需求：安全、短期、可转手。挤兑触发：资产信息变敏感、haircut 上升、MMF 跌破 \\(1。政策：流动性工具扩到一级交易商与 CP，等于把最后贷款人边界外推。宏观：\\)\\phi$ 约束突然收紧，与 GK 的净值冲击同向。</p>',8)),(e(),l(c,null,{default:r(()=>[h(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ABS%5B%22%E9%95%BF%E6%9C%9F%E8%B5%84%E4%BA%A7%22%5D%20--%3E%20ST%5B%22ABCP%20%2F%20%E5%9B%9E%E8%B4%AD%22%5D%0A%20%20ST%20--%3E%20INS%5B%22%E4%BF%A1%E6%81%AF%E4%B8%8D%E6%95%8F%E6%84%9F%E7%9F%AD%E5%80%BA%22%5D%0A%20%20NEWS%5B%22%E4%BF%A1%E6%81%AF%E5%8F%98%E6%95%8F%E6%84%9F%22%5D%20--%3E%20HC%5B%22haircut%20%E4%B8%8A%E5%8D%87%22%5D%0A%20%20HC%20--%3E%20RUN%5B%22%E5%81%9C%E6%BB%9A%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>信息不敏感债在好状态下不需要尽调，所以便宜；坏状态一开始，所有人都要尽调，市场冻结（Dang–Gorton–Holmström）。haircut 是抵押品风险的价格，跳升就是挤兑税。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不是所有非银都是影子银行。保险公司长期负债不是同一挤兑。下一课看央行如何用资产负债表承接停滚后的资产。不写 2010 年后每一条 SEC MMF 改革细则。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>影子挤兑是停滚与 haircut，不是柜面。</li><li>信息不敏感短债在坏状态下集体尽调，市场冻结。</li><li>出处：Gorton and Metrick, <em>JFE</em> 2012；Covitz, Liang and Suarez 的 ABCP。</li></ul>',6))])}const P=n(p,[["render",u]]);export{C as __pageData,P as default};
